+  try {
+    validateSkillName(name);
+  } catch {
+    return undefined;
+  }
+  return name;
+}
+
+function isManagedDirectoryName(directoryName: string): boolean {
+  return (
+    directoryName.startsWith(AUTO_SKILL_PREFIX) &&
+    path.basename(directoryName) === directoryName
